{
  "type": "2x2 日本数字广告横幅网格",
  "layout": {
    "structure": "4个相等的象限",
    "quadrants": [
      {
        "position": "左上",
        "theme": "旅行",
        "subject": "一对情侣在白色沙滩上手牵手，望着碧蓝的海洋水，在明亮的蓝色天空下。",
        "elements": ["左下角的红色芙蓉花"],
        "text_labels": [
          "今年，终于解放。",
          "{argument name=\"travel destination\" default=\"沖縄旅行\"}",
          "3天的治愈之旅",
          "机票+酒店",
          "39,800日元起",
          "绝景、美食、体验 全部实现!"
        ],
        "icons": {
          "count": 3,
          "descriptions": ["飞机", "酒店建筑", "汽车"]
        }
      },
      {
        "position": "右上",
        "theme": "护肤",
        "subject": "年轻女子的特写肖像，皮肤发光、水润，眼睛闭上，轻触脸颊。",
        "elements": [
          "柔和的粉色渐变背景",
          "动态水花效果",
          "标记为'{argument name=\"skincare product name\" default=\"LUMIÈRE\"} 亮肤凝胶'的粉色化妆品罐"
        ],
        "text_labels": [
          "毛孔・暗沉毕业!",
          "充满透明感",
          "水光肌",
          "新感觉护肤",
          "首次限定 78%折扣",
          "{argument name=\"discount price\" default=\"1,980円\"}"
        ],
        "badges": {
          "count": 3,
          "style": "金色圆形",
          "labels": ["毛孔护理", "高保湿", "弹性・光泽"]
        }
      },
      {
        "position": "左下",
        "theme": "美食",
        "subject": "厚切、五分熟牛排，在深色烤盘上滋滋作响。",
        "elements": [
          "蒜片",
          "迷迭香枝",
          "带有烟雾和发光余烬的深色背景"
        ],
        "text_labels": [
          "融化般的美味!",
          "{argument name=\"food item\" default=\"黒毛和牛\"}",
          "奢华牛排",
          "限时",
          "特别价格",
          "常规价格 8,980日元",
          "4,980日元"
        ],
        "badges": {
          "count": 1,
          "style": "红色圆形",
          "labels": ["A4 A5等级"]
        }
      },
      {
        "position": "右下",
        "theme": "在线教育",
        "subject": "穿蓝色衬衫的年轻男子在书桌前学习，在打开的笔记本电脑旁写笔记本。",
        "elements": ["明亮的室内照明", "书桌环境"],
        "text_labels": [
          "利用碎片时间",
          "{argument name=\"education goal\" default=\"最短合格!\"}",
          "在线资格课程",
          "用智能手机完成",
          "高效学习创造差距!",
          "仅限现在! 学费 20%折扣"
        ],
        "badges": {
          "count": 1,
          "style": "蓝色圆形",
          "labels": ["学员数突破10万人!"]
        },
        "icons": {
          "count": 2,
          "descriptions": ["智能手机", "打开的书"]
        }
      }
    ]
  }
}
